class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i, n):
                ok = True
                lst = -1
                for k in range(n):
                    if i <= k <= j:
                        if lst < nums[k]:
                            lst = nums[k]
                        else:
                            ok = False
                            break
                    else:
                        if lst < nums[k]:
                            lst = nums[k]
                        else:
                            ok = False
                            break
                if ok:
                    ans += 1
        return ans
